<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { Instance } from '../../shared/model'
import type { ModFile } from '../../shared/resources'
import { api, run, toast } from '../store'
import Icon from './Icon.vue'
const props=defineProps<{instance:Instance;embedded?:boolean}>(),emit=defineEmits<{close:[];download:[]}>()
type ModRow = ModFile & { links?:{id:string;name:string;kind:string;missing?:boolean}[]; ids?:string[]; issue?:string }
const files=ref<ModRow[]>([]),query=ref(''),loading=ref(false)
const selected=ref<Set<string>>(new Set()),expand=ref<string|null>(null),infoFile=ref<string|null>(null)
const updates=ref<Record<string,{file:string;filename:string;url:string;sha1:string;version:string}>>({}),checking=ref(false),deps=ref<{ok:boolean;checked:number;missing:any[];duplicates:any[]}|null>(null),depsBusy=ref(false)
const updateCount=computed(()=>Object.keys(updates.value).length)
async function checkUpdates(){checking.value=true;try{const list=await api<{file:string;filename:string;url:string;sha1:string;version:string}[]>('mods.updates',{id:props.instance.id});const map:Record<string,any>={};for(const row of list)map[row.file]=row;updates.value=map;toast(Object.keys(map).length?'发现 '+Object.keys(map).length+' 个可更新模组':'所有模组都是最新版')}catch(e:any){toast('检查更新失败：'+e.message)}finally{checking.value=false}}
async function checkDeps(){depsBusy.value=true;try{deps.value=await api('mods.deps',{id:props.instance.id});const r=deps.value as any;toast(r.ok?'依赖检查通过':'发现 '+(r.missing.length+r.duplicates.length)+' 个依赖问题')}catch(e:any){toast('依赖检查失败：'+e.message)}finally{depsBusy.value=false}}
async function applyUpdate(row:ModRow){const update=updates.value[row.file];if(!update)return;loading.value=true;try{const result=await api('mods.update',{id:props.instance.id,update});if(result){files.value=result as ModRow[];const next={...updates.value};delete next[row.file];updates.value=next;toast('已更新 '+row.name)}}catch(e:any){toast('更新失败：'+e.message)}finally{loading.value=false}}
const filtered=computed(()=>files.value.filter(f=>(f.name+' '+f.file).toLowerCase().includes(query.value.toLowerCase())))
const locked=computed(()=>props.instance.running||props.instance.protected)
async function action(method:string,file?:string){loading.value=true;try{const result=await run('mods-'+props.instance.id,method,file?{id:props.instance.id,file}:props.instance.id);if(result)files.value=result as ModRow[]}finally{loading.value=false}}
async function reveal(file:ModRow){loading.value=true;try{await run('mods-reveal','mods.reveal',{id:props.instance.id,file:file.file})}finally{loading.value=false}}
function toggleSelect(name:string){const next=new Set(selected.value);if(next.has(name))next.delete(name);else next.add(name);selected.value=next}
async function batch(kind:string){if(!selected.value.size)return;loading.value=true;try{const result=await run('mods-batch','mods.batch',{id:props.instance.id,action:kind,files:[...selected.value]});if(result){files.value=result as ModRow[];selected.value=new Set()}}finally{loading.value=false}}
onMounted(()=>action('mods.list'))
</script>
<template><div :class="embedded?'mods-embedded':'modal-backdrop'" @click.self="embedded?undefined:emit('close')"><section class="modal mods-modal" :class="{embedded}"><header><h2>{{instance.name}} · Mod 管理</h2><button class="bare" aria-label="关闭 Mod 管理" @click="emit('close')"><Icon name="x"/></button></header><div class="modal-body"><p class="field-hint">{{instance.gameDir}} / mods</p><p v-if="!instance.isolated" class="inline-notice">此实例使用共享游戏目录，这里的修改也会影响使用相同目录的其他实例。</p><p v-if="locked" class="inline-notice">实例已保护或正在运行，目前只能查看。</p><div class="mod-toolbar"><input v-model="query" class="full-input" aria-label="搜索模组" placeholder="搜索模组名称或文件…"/><button class="button compact" :disabled="loading" @click="action('mods.list')">刷新</button><button class="button compact" :disabled="locked||loading" @click="action('mods.import')">导入</button><button class="button compact" :disabled="loading||checking" @click="checkUpdates">{{checking?'检查中…':'检查更新'}}</button><button class="button compact" :disabled="loading||depsBusy" @click="checkDeps">{{depsBusy?'检查中…':'依赖检查'}}</button><button class="button primary compact" @click="emit('download')">下载 Mod</button></div><div v-if="deps" class="deps-panel"><div class="deps-head"><b>{{deps.ok?'依赖完整':'发现 '+(deps.missing.length+deps.duplicates.length)+' 个问题'}}</b><span>已检查 {{deps.checked}} 个模组</span><button class="bare" aria-label="关闭依赖结果" @click="deps=null"><Icon name="x" :size="13"/></button></div><div v-for="m in deps.missing.slice(0,8)" :key="m.file+m.dep" class="deps-row">缺少 <b>{{m.dep}}</b> · {{m.name}}</div><div v-for="d in deps.duplicates" :key="d.id" class="deps-row">重复安装 <b>{{d.id}}</b> · {{d.files.length}} 个文件</div></div><div v-if="selected.size" class="mod-batch"><span>已选 {{selected.size}} 个</span><button class="button compact" :disabled="locked||loading" @click="batch('enable')">启用</button><button class="button compact" :disabled="locked||loading" @click="batch('disable')">禁用</button><button class="button compact danger-text" :disabled="locked||loading" @click="batch('delete')">删除</button><button class="bare" @click="selected=new Set()">取消</button></div><p v-if="!files.length" class="field-hint">{{loading?'正在读取模组…':'尚无模组，可导入本地 JAR 或下载兼容模组。'}}</p><div v-for="file in filtered" :key="file.file" class="mod-row" :class="{disabled:!file.enabled}"><label class="mod-check"><input type="checkbox" :checked="selected.has(file.file)" :aria-label="'选择 '+file.name" @change="toggleSelect(file.file)"/></label><img v-if="file.icon" class="mod-icon" :src="file.icon" alt=""/><span v-else class="mod-icon fallback">{{file.name.slice(0,1)}}</span><div class="mod-main"><b>{{file.name}}</b><small>{{file.version||'未提供版本'}} · {{(file.size/1048576).toFixed(2)}} MiB · {{file.enabled?'已启用':'已禁用'}}</small><p>{{file.file}}</p><p v-if="file.issue" class="danger-text">{{file.issue}}</p><button v-if="file.links&&file.links.length" class="mod-link-toggle" @click="expand=expand===file.file?null:file.file"><Icon name="link" :size="12"/>关系 {{file.links.length}}</button><div v-if="expand===file.file" class="mod-links"><div v-for="link in file.links" :key="link.kind+link.id+link.name"><span class="relation-kind" :class="link.kind">{{link.kind==='depends'?'依赖':'被依赖'}}</span><span class="relation-name">{{link.name}}</span><span v-if="link.missing" class="danger-text">缺失</span></div></div><div v-if="infoFile===file.file" class="mod-info"><div><span>文件</span><b>{{file.file}}</b></div><div><span>版本</span><b>{{file.version||'未提供'}}</b></div><div><span>大小</span><b>{{(file.size/1048576).toFixed(2)}} MiB</b></div><div><span>ID</span><b>{{(file.ids||[]).join('、')||'未提供'}}</b></div><div><span>状态</span><b>{{file.enabled?'已启用':'已禁用'}}</b></div></div></div><div class="mod-actions"><span v-if="updates[file.file]" class="update-badge">→ {{updates[file.file].version}}</span><button v-if="updates[file.file]" class="icon-btn" data-tip="更新模组" :disabled="locked||loading" @click="applyUpdate(file)"><Icon name="download" :size="16"/></button><button class="icon-btn" :data-tip="file.enabled?'禁用':'启用'" :disabled="locked||loading" @click="action('mods.toggle',file.file)"><Icon :name="file.enabled?'check':'x'" :size="16"/></button><button class="icon-btn" :data-tip="infoFile===file.file?'收起信息':'模组信息'" @click="infoFile=infoFile===file.file?null:file.file"><Icon name="help" :size="16"/></button><button class="icon-btn" data-tip="打开文件位置" :disabled="loading" @click="reveal(file)"><Icon name="folder" :size="16"/></button><button class="icon-btn danger" data-tip="删除" :disabled="locked||loading" @click="action('mods.delete',file.file)"><Icon name="trash" :size="16"/></button></div></div></div><footer><span class="field-hint">{{files.length}} 个模组</span><button class="button" @click="emit('close')">关闭</button></footer></section></div></template>
